import { type ClassValue, clsx } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

/**
 * tailwind-merge files `shadow-<name>` under box-shadow only for the t-shirt
 * sizes; every other name falls through to the shadow-COLOR group, where it no
 * longer conflicts with `shadow-md` or `shadow-none`. The design system's
 * boxShadow keys are words, so they have to be declared here or a caller's
 * `className="shadow-none"` would land beside one instead of replacing it.
 */
const twMerge = extendTailwindMerge({
  extend: {
    classGroups: {
      shadow: [
        {
          shadow: [
            "bevel",
            "bevel-light",
            "bevel-dark",
            "card-bevel",
            "hairline",
            "card-hairline",
            "sm-bevel-dark",
            "md-bevel-light",
            "md-bevel-dark",
          ],
        },
      ],
    },
  },
});

/**
 * Combines class names using clsx and tailwind-merge
 * Ensures Tailwind classes are properly merged without conflicts
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
